        'BJAZ_TPA_CLAIM_DETAILS_WS' as SOURCE_VIEW,
        cast(PROCEDURE_DESCRIPTION_LEVEL1 as varchar) as ATTRIBUTE_VALUE
    from {{ ref('stage_tpa_claim_details_ws') }}
    where HUB_CLAIM_BK__BJAZ_CLAIM_ID is not null
    union all
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__CLID))) as HUB_CLAIM_HK,
        'SURGEON_FEE' as ATTRIBUTE_NAME,
        'opus_health_legacy_v4' as SOURCE_RUN,
        'BJAZ_HM_HCM_EXTRACT' as SOURCE_VIEW,
        cast(SURGEON_CHARGES as varchar) as ATTRIBUTE_VALUE
    from {{ ref('stage_hm_hcm_extract') }}
    where HUB_CLAIM_BK__CLID is not null
    union all
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__BJAZ_CLAIM_ID))) as HUB_CLAIM_HK,
        'SURGEON_FEE' as ATTRIBUTE_NAME,
        'opus_health_legacy_v4' as SOURCE_RUN,
        'BJAZ_TPA_CLAIM_DETAILS_WS' as SOURCE_VIEW,
        cast(SURGEON_CHARGES as varchar) as ATTRIBUTE_VALUE
    from {{ ref('stage_tpa_claim_details_ws') }}
    where HUB_CLAIM_BK__BJAZ_CLAIM_ID is not null
    union all
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__CLID))) as HUB_CLAIM_HK,
        'NURSING_CHARGES' as ATTRIBUTE_NAME,
        'opus_health_legacy_v4' as SOURCE_RUN,
        'BJAZ_HM_HCM_EXTRACT' as SOURCE_VIEW,
        cast(NURSING_CHARGES as varchar) as ATTRIBUTE_VALUE
    from {{ ref('stage_hm_hcm_extract') }}
    where HUB_CLAIM_BK__CLID is not null
    union all
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__BJAZ_CLAIM_ID))) as HUB_CLAIM_HK,
        'NURSING_CHARGES' as ATTRIBUTE_NAME,
        'opus_health_legacy_v4' as SOURCE_RUN,
        'BJAZ_TPA_CLAIM_DETAILS_WS' as SOURCE_VIEW,
        cast(NURSING_FEES as varchar) as ATTRIBUTE_VALUE
    from {{ ref('stage_tpa_claim_details_ws') }}
    where HUB_CLAIM_BK__BJAZ_CLAIM_ID is not null
    union all
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__CLID))) as HUB_CLAIM_HK,
        'ICU_CHARGES_AMOUNT' as ATTRIBUTE_NAME,
        'opus_health_legacy_v4' as SOURCE_RUN,
        'BJAZ_HM_HCM_EXTRACT' as SOURCE_VIEW,
        cast(ICU_CHARGES as varchar) as ATTRIBUTE_VALUE
    from {{ ref('stage_hm_hcm_extract') }}
    where HUB_CLAIM_BK__CLID is not null
    union all
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__BJAZ_CLAIM_ID))) as HUB_CLAIM_HK,
        'ICU_CHARGES_AMOUNT' as ATTRIBUTE_NAME,
        'opus_health_legacy_v4' as SOURCE_RUN,
        'BJAZ_TPA_CLAIM_DETAILS_WS' as SOURCE_VIEW,
        cast(ICUCHARGES as varchar) as ATTRIBUTE_VALUE
    from {{ ref('stage_tpa_claim_details_ws') }}
    where HUB_CLAIM_BK__BJAZ_CLAIM_ID is not null
    union all
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__CLAIM_NO))) as HUB_CLAIM_HK,
        'PRE_AUTHORISATION_AMOUNT' as ATTRIBUTE_NAME,
        'opus_health_legacy_v4' as SOURCE_RUN,
        'BJAZ_REMEDINET_CLAIM_DETAILS' as SOURCE_VIEW,
        cast(PREAUTH_AMOUNT as varchar) as ATTRIBUTE_VALUE
    from {{ ref('stage_remedinet_claim_details') }}
    where HUB_CLAIM_BK__CLAIM_NO is not null
    union all
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__BJAZ_CLAIM_ID))) as HUB_CLAIM_HK,
        'PRE_AUTHORISATION_AMOUNT' as ATTRIBUTE_NAME,
        'opus_health_legacy_v4' as SOURCE_RUN,
        'BJAZ_TPA_CLAIM_DETAILS_WS' as SOURCE_VIEW,
        cast(PRE_AUTH_AMOUNT as varchar) as ATTRIBUTE_VALUE
    from {{ ref('stage_tpa_claim_details_ws') }}
    where HUB_CLAIM_BK__BJAZ_CLAIM_ID is not null
    union all
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__CLAIM_ID))) as HUB_CLAIM_HK,
        'TREATING_DOCTOR_NAME' as ATTRIBUTE_NAME,
        'opus_health_v2' as SOURCE_RUN,
        'BJAZ_HM_HCS_TECH_ASSESS_COV' as SOURCE_VIEW,
        cast(TREAT_DR as varchar) as ATTRIBUTE_VALUE
    from {{ ref('stage_hm_hcs_tech_assess_cov') }}
    where HUB_CLAIM_BK__CLAIM_ID is not null
    union all
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__CLAIM_ID))) as HUB_CLAIM_HK,
        'TREATING_DOCTOR_NAME' as ATTRIBUTE_NAME,
        'opus_health_v2' as SOURCE_RUN,
        'BJAZ_HM_PREAUTH_REQUEST' as SOURCE_VIEW,
        cast(TREATING_DOC_NAME as varchar) as ATTRIBUTE_VALUE
    from {{ ref('stage_hm_preauth_request') }}
    where HUB_CLAIM_BK__CLAIM_ID is not null
)

select
    HUB_CLAIM_HK,
    ATTRIBUTE_NAME,
    SOURCE_RUN,
    count(distinct ATTRIBUTE_VALUE) as DISTINCT_VALUES_FROM_ONE_RUN,
    count(distinct SOURCE_VIEW) as SOURCE_VIEWS_DISAGREEING
from undiscriminated
where ATTRIBUTE_VALUE is not null
group by HUB_CLAIM_HK, ATTRIBUTE_NAME, SOURCE_RUN
having count(distinct ATTRIBUTE_VALUE) > 1
